package main

import (
 "fmt"
 "image"
 "image/color"
 "image/jpeg"
 "os"
 "strconv"
)

func main(){
 if len(os.Args)<5 {fmt.Println("usage: gen out w h mode [arg]"); return}
 out:=os.Args[1]; w,_:=strconv.Atoi(os.Args[2]); h,_:=strconv.Atoi(os.Args[3]); mode:=os.Args[4]
 var img image.Image
 switch mode {
 case "gray":
   v,_:=strconv.Atoi(os.Args[5])
   g:=image.NewGray(image.Rect(0,0,w,h))
   for y:=0;y<h;y++ { for x:=0;x<w;x++ { g.SetGray(x,y,color.Gray{uint8(v)}) } }
   img=g
 case "graygradx":
   g:=image.NewGray(image.Rect(0,0,w,h))
   for y:=0;y<h;y++ { for x:=0;x<w;x++ { var v int; if w>1 {v=x*255/(w-1)}; g.SetGray(x,y,color.Gray{uint8(v)}) } }
   img=g
 case "graygrady":
   g:=image.NewGray(image.Rect(0,0,w,h))
   for y:=0;y<h;y++ { for x:=0;x<w;x++ { var v int; if h>1 {v=y*255/(h-1)}; g.SetGray(x,y,color.Gray{uint8(v)}) } }
   img=g
 case "color":
   r,_:=strconv.Atoi(os.Args[5]); gg,_:=strconv.Atoi(os.Args[6]); b,_:=strconv.Atoi(os.Args[7])
   g:=image.NewRGBA(image.Rect(0,0,w,h))
   for y:=0;y<h;y++ { for x:=0;x<w;x++ { g.Set(x,y,color.RGBA{uint8(r),uint8(gg),uint8(b),255}) } }
   img=g
 case "pixels":
   // args are comma list rows? Use file? simpler: values as remaining args row-major grayscale
   g:=image.NewGray(image.Rect(0,0,w,h))
   idx:=5
   for y:=0;y<h;y++ { for x:=0;x<w;x++ { v:=0; if idx<len(os.Args){v,_=strconv.Atoi(os.Args[idx]); idx++}; g.SetGray(x,y,color.Gray{uint8(v)}) } }
   img=g
 case "rgbpixels":
   // each pixel r,g,b as args
   g:=image.NewRGBA(image.Rect(0,0,w,h))
   idx:=5
   for y:=0;y<h;y++ { for x:=0;x<w;x++ { r,gg,b:=0,0,0; if idx+2<len(os.Args){r,_=strconv.Atoi(os.Args[idx]); gg,_=strconv.Atoi(os.Args[idx+1]); b,_=strconv.Atoi(os.Args[idx+2]); idx+=3}; g.Set(x,y,color.RGBA{uint8(r),uint8(gg),uint8(b),255}) } }
   img=g
 }
 f,_:=os.Create(out); defer f.Close()
 // quality 100
 jpeg.Encode(f, img, &jpeg.Options{Quality:100})
}
GO
