import subprocess, os, re
def gen(w,h,func,path="/tmp/p.jpg"):
    vals=[func(x,y) for y in range(h) for x in range(w)]
    subprocess.run(["/tmp/genjpg", path,str(w),str(h),"pixels"]+[str(x) for x in vals], check=True)
def out(args,path="/tmp/p.jpg"):
    p=subprocess.run(["/workspace/executable"]+args+[path], capture_output=True, env={**os.environ,"TERM":"xterm"})
    return p.stdout.decode()
def colorvals(size):
    o=out([f"--size={size}","--chars=0123456789","--html","--html-raw","--colors"])
    # extract #rrggbb and char
    pairs=re.findall(r"color:#([0-9a-fA-F]{6});'>(.)</span>", o)
    return o, pairs

gen(64,64, lambda x,y: 255 if 16<=y<24 else 0)
for size in ["1x8","1x16","1x4","1x64","1x32"]:
    o,pairs=colorvals(size)
    print(size, pairs)
print()
gen(64,64, lambda x,y: 255 if 16<=x<24 else 0)
for size in ["8x1","16x1","4x1","64x1","32x1"]:
    o,pairs=colorvals(size)
    print(size, pairs)
PY"}

