{"command":"cat > /tmp/jscan.c << 'C'
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <setjmp.h>
extern void *jpeg_std_error(void *err);
extern void jpeg_CreateDecompress(void *cinfo, int version, size_t structsize);
extern void jpeg_destroy_decompress(void *cinfo);
extern void jpeg_stdio_src(void *cinfo, FILE *fp);
extern int jpeg_read_header(void *cinfo, int require_image);
extern int jpeg_start_decompress(void *cinfo);
extern unsigned int jpeg_read_scanlines(void *cinfo, unsigned char **scanlines, unsigned int num_lines);
extern int jpeg_finish_decompress(void *cinfo);
static jmp_buf jb;
static void my_error_exit(void *cinfo){
  // error mgr format_message at offset 24? pointers: error_exit0 emit8 output16 format24 reset32
  void *err=*(void**)cinfo;
  char buf[1024];
  void (*fmt)(void*,char*) = *(void**)((char*)err+24);
  fmt(cinfo,buf);
  fprintf(stderr,"LIBJPEG ERROR: %s\n",buf);
  longjmp(jb,1);
}
static void dump_ints(void *cinfo,const char*label){
  printf("-- %s --\n",label);
  for(int off=0; off<656; off+=4){
    unsigned int v=*(unsigned int*)((char*)cinfo+off);
    if(v!=0) printf(" off %3d u32=%u (0x%x) i32=%d\n",off,v,v,(int)v);
  }
}
int main(int argc,char**argv){
 void *err=calloc(1,2048);
 void *cinfo=calloc(1,65536);
 jpeg_std_error(err);
 *(void**)err=my_error_exit;
 *(void**)cinfo=err;
 jpeg_CreateDecompress(cinfo,80,656);
 if(setjmp(jb)){ printf("caught\n"); return 2; }
 FILE *fp=fopen(argv[1],"rb");
 jpeg_stdio_src(cinfo,fp);
 int r=jpeg_read_header(cinfo,1);
 printf("read_header=%d\n",r);
 dump_ints(cinfo,"after header");
 // Optionally set out_color_space if arg3 as offset/value
 if(argc>3){ int off=atoi(argv[2]); int val=atoi(argv[3]); *(int*)((char*)cinfo+off)=val; printf("set off%d=%d\n",off,val);}
 jpeg_start_decompress(cinfo);
 dump_ints(cinfo,"after start");
 // try scanline allocation based guessed output_width maybe find values in manual
 fclose(fp);
 jpeg_destroy_decompress(cinfo);
 return 0;
}
