{"command":"cat > /tmp/jscan2.c << 'C'
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <setjmp.h>
#include <stdint.h>
extern void *jpeg_std_error(void *err);
extern void jpeg_CreateDecompress(void *cinfo, int version, size_t structsize);
extern void jpeg_destroy_decompress(void *cinfo);
extern void jpeg_stdio_src(void *cinfo, FILE *fp);
extern void jpeg_mem_src(void *cinfo, const unsigned char *data, unsigned long len);
extern int jpeg_read_header(void *cinfo, int require_image);
extern int jpeg_start_decompress(void *cinfo);
extern unsigned int jpeg_read_scanlines(void *cinfo, unsigned char **scanlines, unsigned int num_lines);
static jmp_buf jb;
static void my_error_exit(void *cinfo){ void *err=*(void**)cinfo; char buf[1024]; void (*fmt)(void*,char*)=*(void**)((char*)err+24); fmt(cinfo,buf); fprintf(stderr,"ERR %s\n",buf); longjmp(jb,1);}
static void dump(void*c,const char *l){
 printf("--%s\n",l);
 for(int off=0;off<220;off+=8){ uint64_t v=*(uint64_t*)((char*)c+off); unsigned int a=*(unsigned int*)((char*)c+off), b=*(unsigned int*)((char*)c+off+4); double d=*(double*)((char*)c+off); printf("%3d: u64=%016lx u32=[%u,%u] double=%g\n",off,(unsigned long)v,a,b,d);}
}
int main(int argc,char**argv){
 void *err=calloc(1,2048); void *cinfo=calloc(1,65536); jpeg_std_error(err); *(void**)err=my_error_exit; *(void**)cinfo=err; jpeg_CreateDecompress(cinfo,80,656);
 if(setjmp(jb)) return 2;
 FILE *fp=fopen(argv[1],"rb"); jpeg_stdio_src(cinfo,fp); jpeg_read_header(cinfo,1); dump(cinfo,"header");
 if(argc>3){int off=atoi(argv[2]); int val=atoi(argv[3]); *(int*)((char*)cinfo+off)=val; printf("SET off %d to %d\n",off,val);}
 jpeg_start_decompress(cinfo); dump(cinfo,"start");
 unsigned int ow=*(unsigned int*)((char*)cinfo+136), oh=*(unsigned int*)((char*)cinfo+140); int oc=*(int*)((char*)cinfo+148);
 printf("guessed ow=%u oh=%u output_comp(offset148)=%d offset144=%d\n",ow,oh,oc,*(int*)((char*)cinfo+144));
 unsigned char *row=malloc(ow*oc+100);
 for(unsigned int y=0;y<oh;y++){ unsigned char *rows[1]={row}; unsigned int n=jpeg_read_scanlines(cinfo,rows,1); if(y<2||y>=oh-1){printf("row %u n=%u first bytes:",y,n); for(int i=0;i< (ow*oc<20?ow*oc:20);i++) printf(" %u",row[i]); printf("\n");}}
 fclose(fp); jpeg_destroy_decompress(cinfo); return 0;
}
