{"command":"cat > /tmp/probe2.py << 'PY'
import subprocess, os
def run(args, stdin=None, env=None):
    e={**os.environ,"TERM":"xterm"}
    if env:
        for k,v in env.items():
            if v is None: e.pop(k,None)
            else: e[k]=v
    return subprocess.run(["/workspace/executable"]+args, input=stdin, capture_output=True, env=e)
def show(args, **kw):
    p=run(args,**kw)
    out=p.stdout; err=p.stderr
    # summarize help
    def summ(b):
        if b.startswith(b"Unknown option") or b.startswith(b"No files"):
            return b.split(b"\n")[0]+b" +HELP" if len(b)>200 else b
        if len(b)>300: return b[:300]+b"..."
        return b
    print(f"{args!r} exit={p.returncode} out={summ(out)!r} err={summ(err)!r}")
