    p=subprocess.run(["/workspace/executable"]+args,capture_output=True,env={**os.environ,"TERM":"xterm","COLUMNS":str(cols),"LINES":str(lines)},timeout=3)
    rows=p.stdout.splitlines(); d=(len(rows[0]) if rows else 0,len(rows))
    if border and d[0]: d=(d[0]-2,d[1]-2)
    return d,p.returncode
def rnd(x): return math.floor(x+0.5)
def fromw(sw,sh,w):
    h=rnd(w*sh/sw*0.5); return ((sw+sh-1)//sh,1) if h==0 else (w,h)
def fromh(sw,sh,h):
    w=rnd(h*sw/sh*2); return (1,(sh+4*sw-1)//(4*sw)) if w==0 else (w,h)
def pred(sw,sh,cols,lines,border,mode):
    tw=cols-(2 if border else 0); th=lines-(2 if border else 0)
    if mode=="fit":
        w,h=fromw(sw,sh,tw)
        if tw>th and h>=th: w,h=fromh(sw,sh,th-1)
        return (w,h)
    if mode=="tw": return fromw(sw,sh,tw)
    if mode=="th": return fromh(sw,sh,th-1)
    return (tw,th-1)
fails=total=0
for sw,sh in [(40,25),(320,240),(64,64),(24,100),(100,24),(123,45),(45,123)]:
    subprocess.run(["/tmp/genjpg","/tmp/s.jpg",str(sw),str(sh),"gray","128"],check=True,capture_output=True)
    for cols,lines in [(80,24),(40,10),(100,50),(10,5),(20,20),(5,100),(100,5),(50,50),(30,40)]:
        for border in [False,True]:
            for mode,opt in [("fit","--term-fit"),("tw","--term-width"),("th","--term-height"),("zoom","--term-zoom")]:
                obs,rc=dims((["-b"] if border else [])+[opt,"/tmp/s.jpg"],cols,lines,border); pr=pred(sw,sh,cols,lines,border,mode); total+=1
                if rc!=0 or obs!=pr: print("FAIL",sw,sh,cols,lines,border,mode,obs,rc,pr);fails+=1
print(total,fails)
