        elif self.path=='/text': b'hello'; self.send_response(200);self.send_header('Content-Length','5');self.end_headers();self.wfile.write(b'hello')
        elif self.path=='/img.jpg': self.send_response(200);self.send_header('Content-Type','image/jpeg');self.send_header('Content-Length',str(len(img)));self.end_headers();self.wfile.write(img)
        elif self.path=='/empty': self.send_response(200);self.send_header('Content-Length','0');self.end_headers()
