import os,pty,sys,fcntl,termios,struct,select,signal
def run_pty(cols,lines,args,env_extra=None,stdout_to_pty=True,stdin_to_pty=False,stderr_to_pty=False):
    master,slave=pty.openpty()
    # set winsize on slave: rows, cols, xpixel, ypixel
    fcntl.ioctl(slave, termios.TIOCSWINSZ, struct.pack("HHHH",lines,cols,0,0))
    env=dict(os.environ); env["TERM"]="xterm"; env.pop("COLUMNS",None);env.pop("LINES",None)
    if env_extra: env.update(env_extra)
    pid=os.fork()
    if pid==0:
        os.setsid()
        # controlling terminal?
        fcntl.ioctl(slave, termios.TIOCSCTTY, 0)
        if stdin_to_pty: os.dup2(slave,0)
        else:
            devnull=os.open(os.devnull,os.O_RDONLY);os.dup2(devnull,0)
        if stdout_to_pty: os.dup2(slave,1)
