import os,pty,fcntl,termios,struct
def run(stdout_tty,stdin_tty,stderr_tty,cols=33,lines=12):
    m,s=pty.openpty();fcntl.ioctl(s,termios.TIOCSWINSZ,struct.pack("HHHH",lines,cols,0,0))
    outpath="/tmp/ptyout.txt";errpath="/tmp/ptyerr.txt";
    pid=os.fork()
    if pid==0:
        os.setsid();fcntl.ioctl(s,termios.TIOCSCTTY,0)
        # stdin
        if stdin_tty:os.dup2(s,0)
        else:
            fd=os.open(os.devnull,os.O_RDONLY);os.dup2(fd,0)
        if stdout_tty:os.dup2(s,1)
        else:
            fd=os.open(outpath,os.O_WRONLY|os.O_CREAT|os.O_TRUNC,0o644);os.dup2(fd,1)
        if stderr_tty:os.dup2(s,2)
        else:
            fd=os.open(errpath,os.O_WRONLY|os.O_CREAT|os.O_TRUNC,0o644);os.dup2(fd,2)
        os.close(m);os.close(s)
        env=dict(os.environ,TERM="xterm");env.pop("COLUMNS",None);env.pop("LINES",None)
        os.execve("/workspace/executable",["x","assets/logo-40x25-gray.jpg"],env)
    os.close(s)
    data=b""
    # read pty if any output there, nonblocking-ish: set master nonblocking after child exits maybe
    _,st=os.waitpid(pid,0)
    # try read available
    import select
    while True:
        r,_,_=select.select([m],[],[],0.2)
        if not r:break
        try:d=os.read(m,65536)
        except:break
        if not d:break
        data+=d
    os.close(m)
    filedata=open(outpath,'rb').read() if os.path.exists(outpath) else b""
    chosen=data if stdout_tty else filedata
    rows=chosen.splitlines();print(f"stdout_tty={stdout_tty} stdin={stdin_tty} stderr={stderr_tty} dims={(len(rows[0].strip()) if rows else 0,len(rows))} status={st} errfile={open(errpath,'rb').read()[:100]}")
