// ---- options / globals ----
static char palette_buf[257];
static float opt_red = 0.2989f, opt_green = 0.5866f, opt_blue = 0.1145f;
static int opt_border=0, opt_clear=0, opt_colors=0, opt_debug=0, opt_fill=0;
