static const char VERSION_TEXT[] =
"jp2a 1.0.8\n"
"Copyright 2006-2016 Christian Stigen Larsen\n"
"Distributed under the GNU General Public License (GPL) v2.\n";

// ---- options / globals ----
static char palette_buf[257];
static float opt_red = 0.2989f, opt_green = 0.5866f, opt_blue = 0.1145f;
static int opt_border=0, opt_clear=0, opt_colors=0, opt_debug=0, opt_fill=0;
static int opt_flipx=0, opt_flipy=0, opt_grayscale=0, opt_html=0;
static int opt_html_no_bold=0, opt_html_raw=0, opt_invert=0, opt_verbose=0;
static int html_fontsize = 8;
static const char *html_title = "jp2a converted image";
static const char *output_name = NULL;
static int opt_width=0, opt_height=0;
static int width_given=0, height_given=0;
enum { TM_NONE=0, TM_FIT, TM_WIDTH, TM_HEIGHT, TM_ZOOM };
static int term_mode = TM_NONE;
static int term_cols=80, term_lines=24;
static int term_tw=80, term_th=24; // after border subtraction (th is before -1 prompt row)

static char **files=NULL;
static int num_files=0, files_cap=0;
static FILE *out_fp=NULL;
static int processed_images=0;

static void add_file(char *s){
    if(num_files>=files_cap){ files_cap=files_cap?files_cap*2:16; files=realloc(files,files_cap*sizeof(char*)); }
    files[num_files++]=s;
}
static int starts_with(const char *s,const char *pre){ return strncmp(s,pre,strlen(pre))==0; }
static int64_t round_div_i64(int64_t num,int64_t den){ // round(num/den), num>=0 den>0, half up
    if(den<=0) return 0;
    return (2*num + den) / (2*den);
}
static int64_t ceil_div_i64(int64_t num,int64_t den){
    if(den<=0) return 0;
    if(num<=0) return num/den;
    return (num + den - 1)/den;
}
// calc out height from width (may adjust width on fallback), aspect factor 0.5
static void dims_from_width(int srcw,int srch,int64_t *w_io,int64_t *h_out){
    int64_t w=*w_io;
    int64_t h = round_div_i64(w*(int64_t)srch, 2LL*(int64_t)srcw);
    if(h==0){ h=1; w=ceil_div_i64(srcw,srch); *w_io=w; }
    *h_out=h;
}
static void dims_from_height(int srcw,int srch,int64_t *w_out,int64_t *h_io){
    int64_t h=*h_io;
    int64_t w = round_div_i64(2LL*h*(int64_t)srcw, (int64_t)srch);
    if(w==0){ w=1; h=ceil_div_i64(srch,4LL*(int64_t)srcw); *h_io=h; }
    *w_out=w;
}
static void compute_output_dims(int srcw,int srch,int64_t *outw,int64_t *outh){
    int64_t w=opt_width, h=opt_height;
    if(term_mode==TM_ZOOM){ *outw=term_tw; *outh=(int64_t)term_th-1; return; }
    if(term_mode==TM_WIDTH){
        w=term_tw;
        if(height_given){ *outw=w; *outh=0; return; }
        dims_from_width(srcw,srch,&w,&h); *outw=w; *outh=h; return;
    }
    if(term_mode==TM_HEIGHT){
        h=(int64_t)term_th-1;
        if(width_given){ *outw=0; *outh=h; return; }
        dims_from_height(srcw,srch,&w,&h); *outw=w; *outh=h; return;
    }
    // fit or none
    if(w==0 && h==0 && !width_given && !height_given){
        // term fit
        int64_t fw=term_tw, fh=0;
        dims_from_width(srcw,srch,&fw,&fh);
        if(term_tw > term_th && fh >= term_th){
            fh=(int64_t)term_th-1;
            dims_from_height(srcw,srch,&fw,&fh);
        }
        *outw=fw; *outh=fh; return;
    }
    if(w==0 && h==0){
        // an explicitly zero width/height: observed to yield terminal height rows of width 0
        *outw=0; *outh=(int64_t)term_th-1; return;
    }
    if(w==0){
        if(width_given){ *outw=0; *outh=h; return; }
        dims_from_height(srcw,srch,&w,&h); *outw=w; *outh=h; return;
    }
    if(h==0){
        if(height_given){ *outw=w; *outh=0; return; }
        dims_from_width(srcw,srch,&w,&h); *outw=w; *outh=h; return;
    }
    *outw=w; *outh=h;
}
static int get_terminal_size(void){
    const char *term=getenv("TERM");
    if(term==NULL){ fprintf(stderr,"Environment variable TERM not set.\n"); return 0; }
    int err=0;
    if(setupterm(NULL,1,&err)==ERR){ fprintf(stderr,"Terminal type '%s' not recognized.\n",term); return 0; }
    term_cols=COLS; term_lines=LINES;
    term_tw=term_cols - (opt_border?2:0);
    term_th=term_lines - (opt_border?2:0);
    return 1;
}
static int invalid_global_dims(void){
    if(opt_width<0 || opt_height<0) return 1;
    if(term_mode==TM_HEIGHT && height_given) return 1;
    if(term_mode==TM_ZOOM){ if(term_tw<=0 || term_th-1<=0) return 1; return 0; }
    if(term_mode==TM_HEIGHT){ if(term_th-1<=0) return 1; return 0; }
    if(term_mode==TM_WIDTH){ if(term_tw<=0) return 1; return 0; }
    if(opt_width==0 && opt_height==0){
        if(height_given && !width_given) return 1; // --height=0 alone
        // fit to a terminal with no usable width (e.g. border + 2 cols)
        if(term_tw<=0) return 1;
        return 0;
    }
    if(opt_width==0){
        if(!width_given && !height_given) return 1; // --size=0xH
        return 0;
    }
    if(opt_height==0){
        if(!width_given && !height_given) return 1; // --size=Wx0
        return 0;
    }
    return 0;
}

// ---- output image ----
typedef struct { float lum,r,g,b; unsigned char ch; } Cell;

static int color_to_int(float v){
    return (int)(v*255.0f + 0.5f);
}
static void html_print_char(FILE *out, unsigned char ch){
    switch(ch){
        case ' ': fputs("&nbsp;",out); break;
        case '&': fputs("&amp;",out); break;
        case '<': fputs("&lt;",out); break;
        case '>': fputs("&gt;",out); break;
        default: fputc(ch,out); break;
    }
}
static void get_display_rgb(const Cell *c,int comps,float *r,float *g,float *b){
    (void)comps;
    if(opt_grayscale){ *r=*g=*b=c->lum; }
    else { *r=c->r; *g=c->g; *b=c->b; }
}
// ANSI classification for RGB cells. Returns 0..7 (black..white) or -1 for code "1" handling elsewhere.
static int rgb_to_ansi_idx(float r,float g,float b){
    float mx=fmaxf(r,fmaxf(g,b));
    float mn=fminf(r,fminf(g,b));
    // achromatic (within tolerance) -> white
    if(mx-mn <= 0.1f) return 7;
    int bits=0;
    if(r >= mx-0.1f) bits|=1;
    if(g >= mx-0.1f) bits|=2;
    if(b >= mx-0.1f) bits|=4;
    // two dominant channels but dim: yellow/cyan become black, magenta becomes white (observed)
    if((bits==3 || bits==6) && mx <= 0.5f) return 0;
    if(bits==5 && mx <= 0.5f) return 7;
    static const int map[8]={0,1,2,3,4,5,6,7}; // bits r=1,g=2,b=4 -> ansi colour index
    // map bits to colour index: 1->red(1),2->green(2),3->yellow(3),4->blue(4),5->magenta(5),6->cyan(6),7->white(7)
    return map[bits];
}
static void print_cell_ansi(FILE *out,const Cell *c,int comps){
    unsigned char ch=c->ch;
    if(opt_grayscale){
        if(c->lum > 0.7f){ fprintf(out,"\033[%dm%c\033[0m", opt_fill?47:37, ch); }
        else fputc(ch,out);
        return;
    }
    // colors (opt_colors guaranteed by caller)
    if(comps!=3){
        if(c->lum==0.0f){ fprintf(out,"\033[%dm%c\033[0m", opt_fill?47:37, ch); }
        else if(c->lum > 0.95f){ fprintf(out,"\033[1m%c\033[0m", ch); }
        else fputc(ch,out);
        return;
    }
    float r=c->r,g=c->g,b=c->b;
    int idx=rgb_to_ansi_idx(r,g,b);
    if(idx==0){ fputc(ch,out); return; }
    int code=(opt_fill?40:30)+idx;
    fprintf(out,"\033[%dm%c\033[0m",code,ch);
}
static void print_image(Cell *cells,int64_t outw,int64_t outh,int comps){
    FILE *out=out_fp;
    int color_active = opt_colors || opt_grayscale;
    if(opt_clear) fputs("\033[2J\033[0;0H",out);
    if(opt_html && !opt_html_raw){
        fputs("<?xml version='1.0' encoding='ISO-8859-1'?>\n",out);
        fputs("<!DOCTYPE html PUBLIC '-//W3C//DTD XHTML 1.0 Strict//EN'  'http://www.w3.org/TR/xhtml1/DTD/xhtml1-strict.dtd'>\n",out);
        fputs("<html xmlns='http://www.w3.org/1999/xhtml' lang='en' xml:lang='en'>\n",out);
        fputs("<head>\n",out);
        fprintf(out,"<title>%s</title>\n",html_title);
        fputs("<style type='text/css'>\n",out);
        fputs("body {\n",out);
        if(opt_invert) fputs("   background-color: white;\n",out); else fputs("background-color: black;\n",out);
        fputs("}\n",out);
        fputs(".ascii {\n",out);
        fputs("   font-family: Courier;\n",out);
        if(!color_active) fprintf(out,"   color: %s;\n", opt_invert?"black":"white");
        fprintf(out,"   font-size:%dpt;\n",html_fontsize);
        fprintf(out,"   font-weight: %s;\n", opt_html_no_bold?"normal":"bold");
        fputs("}\n",out);
        fputs("</style>\n",out);
        fputs("</head>\n",out);
        fputs("<body>\n",out);
        fputs("<div class='ascii'><pre>\n",out);
    }
    // border top
    if(opt_border){
        fputc('+',out); for(int64_t i=0;i<outw;i++) fputc('-',out); fputs("+\n",out);
    }
    // row buffer for plain printing
    char *rowbuf=NULL;
    if(!color_active || !opt_html){
        // plain text mode, or html non-colour: need a row string; for ansi mode we print per-cell below
        (void)rowbuf;
    }
    for(int64_t y=0;y<outh;y++){
        if(opt_border) fputc('|',out);
        if(opt_html && color_active){
            for(int64_t x=0;x<outw;x++){
                Cell *c=&cells[y*outw+x];
                float r,g,b; get_display_rgb(c,comps,&r,&g,&b);
                int R=color_to_int(r),G=color_to_int(g),B=color_to_int(b);
                if(opt_fill){
                    float fr,fg2,fb;
                    if(opt_grayscale || comps!=3){ fr=r*0.5f; fg2=g*0.5f; fb=b*0.5f; }
                    else { fr=r*c->lum; fg2=g*c->lum; fb=b*c->lum; }
                    fprintf(out,"<span style='color:#%02x%02x%02x; background-color:#%02x%02x%02x;'>",color_to_int(fr),color_to_int(fg2),color_to_int(fb),R,G,B);
                } else {
                    fprintf(out,"<span style='color:#%02x%02x%02x;'>",R,G,B);
                }
                html_print_char(out,c->ch);
                fputs("</span>",out);
            }
            if(opt_border) fputc('|',out);
            fputs("<br/>",out);
        } else if(!opt_html && color_active){
            for(int64_t x=0;x<outw;x++) print_cell_ansi(out,&cells[y*outw+x],comps);
            if(opt_border) fputc('|',out);
            fputc('\n',out);
        } else {
            // plain: build a NUL-terminated row and print with %s (matching truncation on NUL chars)
            // Allocate per row to avoid a huge persistent buffer for width 0 etc.
            char *rb=malloc((size_t)(outw+1));
            if(rb){
                for(int64_t x=0;x<outw;x++) rb[x]=(char)cells[y*outw+x].ch;
                rb[outw]='\0';
                fprintf(out,"%s",rb);
                free(rb);
            }
            if(opt_border) fputc('|',out);
            fputc('\n',out);
        }
    }
    if(opt_border){
        fputc('+',out); for(int64_t i=0;i<outw;i++) fputc('-',out); fputs("+\n",out);
    }
    if(opt_html && !opt_html_raw){
        fputs("</pre>\n",out);
        fputs("</div>\n",out);
        fputs("</body>\n",out);
        fputs("</html>\n",out);
    }
    fflush(out);
}

// ---- JPEG loading + conversion ----
static void verbose_progress(int64_t row_index_plus2,int srch){
    // bar width 54, hashes = round(54 * (y+2)/srch)
    int64_t hashes = round_div_i64(54*row_index_plus2, srch);
    if(hashes>=57){
        // The reference overflows a fixed buffer here for very short images.
        fprintf(stderr,"*** buffer overflow detected ***: terminated\n");
        fflush(stderr);
        abort();
    }
    fputs("Decompressing image [",stderr);
    for(int64_t i=0;i<hashes;i++) fputc('#',stderr);
    for(int64_t i=hashes;i<54;i++) fputc('.',stderr);
    fputs("]\r",stderr);
    fflush(stderr);
}
static int process_stream(FILE *in){
    void *err=calloc(1,8192);
    void *cinfo=calloc(1,8192);
    if(!err||!cinfo){ free(err);free(cinfo); fprintf(stderr,"Not enough memory for given output dimension\n"); return 1; }
    jpeg_std_error(err);
    *(void**)cinfo=err;
    jpeg_CreateDecompress(cinfo,J_VERSION,J_STRUCT_SIZE);
    jpeg_stdio_src(cinfo,in);
    jpeg_read_header(cinfo,1);
    int srcw=(int)*(unsigned int*)((char*)cinfo+JOFF_IMAGE_WIDTH);
    int srch=(int)*(unsigned int*)((char*)cinfo+JOFF_IMAGE_HEIGHT);
    int num_comp=*(int*)((char*)cinfo+JOFF_NUM_COMPONENTS);
    int64_t outw=0,outh=0;
    compute_output_dims(srcw,srch,&outw,&outh);
    // memory check (matching the reference's apparent INT_MAX product guard)
    __int128 prod=(__int128)outw*outh;
    if(prod>INT_MAX || outw==INT_MAX){
        fprintf(stderr,"Not enough memory for given output dimension\n");
        jpeg_destroy_decompress(cinfo); free(cinfo); free(err);
        return 1;
    }
    Cell *cells=NULL;
    if(outw>0 && outh>0){
        cells=calloc((size_t)(outw*outh),sizeof(Cell));
        if(!cells){ fprintf(stderr,"Not enough memory for given output dimension\n"); jpeg_destroy_decompress(cinfo); free(cinfo); free(err); return 1; }
    } else {
        cells=calloc(1,sizeof(Cell));
    }
    if(opt_verbose){
        fprintf(stderr,"Source width: %d\n",srcw);
        fprintf(stderr,"Source height: %d\n",srch);
        fprintf(stderr,"Source color components: %d\n",num_comp);
        fprintf(stderr,"Output width: %lld\n",(long long)outw);
        fprintf(stderr,"Output height: %lld\n",(long long)outh);
        fprintf(stderr,"Output palette (%d chars): '%s'\n",(int)strlen(palette_buf),palette_buf);
    }
    jpeg_start_decompress(cinfo);
    int out_comps=*(int*)((char*)cinfo+JOFF_OUTPUT_COMPONENTS);
    int libw=(int)*(unsigned int*)((char*)cinfo+JOFF_OUTPUT_WIDTH);
    int libh=(int)*(unsigned int*)((char*)cinfo+JOFF_OUTPUT_HEIGHT);
    if(libw>0){ srcw=libw; }
    if(libh>0){ srch=libh; }
    if(out_comps<=0) out_comps=num_comp>0?num_comp:1;
    size_t row_stride=(size_t)srcw*out_comps;
    unsigned char *pixels=NULL;
    if(srcw>0 && srch>0){
        pixels=malloc(row_stride*(size_t)srch);
        if(!pixels){ fprintf(stderr,"Not enough memory for given output dimension\n"); free(cells); jpeg_destroy_decompress(cinfo); free(cinfo); free(err); return 1; }
    }
    for(int y=0;y<srch;y++){
        unsigned char *row=pixels+row_stride*(size_t)y;
        unsigned char *rows[1]={row};
        jpeg_read_scanlines(cinfo,rows,1);
        if(opt_verbose) verbose_progress(y+2,srch);
    }
    if(opt_verbose) fputc('\n',stderr);
    jpeg_finish_decompress(cinfo);
    jpeg_destroy_decompress(cinfo);
    free(cinfo); free(err);
    // compute bounds
    if(outw>0 && outh>0 && pixels){
        int64_t *xb=malloc(sizeof(int64_t)*(outw+1));
        int64_t *yb=malloc(sizeof(int64_t)*(outh+1));
        if(!xb||!yb){ free(xb);free(yb);free(pixels);free(cells); fprintf(stderr,"Not enough memory for given output dimension\n"); return 1; }
        for(int64_t k=0;k<=outw;k++) xb[k]=round_div_i64(k*(int64_t)(srcw-1),outw);
        if(outh==1){ yb[0]=0; yb[1]=srch-1; }
        else {
            yb[0]=(processed_images>0 && srch>1)?1:0;
            for(int64_t k=1;k<outh;k++) yb[k]=ceil_div_i64((2*k-1)*(int64_t)(srch-1),2*(outh-1));
            yb[outh]=srch-1;
        }
        int pal_len=(int)strlen(palette_buf);
        for(int64_t oy=0;oy<outh;oy++){
            int64_t y0=yb[oy],y1=yb[oy+1];
            if(y1<y0) y1=y0;
            for(int64_t ox=0;ox<outw;ox++){
                int64_t x0=xb[ox],x1=xb[ox+1];
                if(x1<x0) x1=x0;
                float sumL=0,sumR=0,sumG=0,sumB=0;
                for(int64_t yy=y0;yy<=y1;yy++){
                    const unsigned char *prow=pixels+row_stride*(size_t)yy;
                    for(int64_t xx=x0;xx<=x1;xx++){
                        const unsigned char *p=prow+(size_t)xx*out_comps;
                        if(out_comps==3){
                            float rf=p[0]/255.0f, gf=p[1]/255.0f, bf=p[2]/255.0f;
                            sumR+=rf; sumG+=gf; sumB+=bf;
                            sumL += rf*opt_red + gf*opt_green + bf*opt_blue;
                        } else {
                            float vf=p[0]/255.0f;
                            sumR+=vf; sumG+=vf; sumB+=vf; sumL+=vf;
                        }
                    }
                }
                float count=(float)((x1-x0+1)*(y1-y0+1));
                Cell cell;
                cell.lum=sumL/count; cell.r=sumR/count; cell.g=sumG/count; cell.b=sumB/count;
                float lum=cell.lum;
                if(opt_invert) lum=1.0f-lum;
                int idx=(int)(lum*(pal_len-1)+0.5f);
                unsigned char ch=0;
                if(idx>=0 && idx<=256) ch=(unsigned char)palette_buf[idx];
                else ch=0;
                cell.ch=ch;
                int64_t dx=opt_flipx?(outw-1-ox):ox;
                int64_t dy=opt_flipy?(outh-1-oy):oy;
                cells[dy*outw+dx]=cell;
            }
        }
        free(xb);free(yb);
    }
    free(pixels);
    print_image(cells,outw,outh,out_comps);
    free(cells);
