                Cell *c=&cells[y*outw+x];
                float r,g,b; get_display_rgb(c,comps,&r,&g,&b);
                int R=color_to_int(r),G=color_to_int(g),B=color_to_int(b);
                if(opt_fill){
                    float fr,fg2,fb;
                    if(opt_grayscale || comps!=3){ fr=r*0.5f; fg2=g*0.5f; fb=b*0.5f; }
                    else { fr=r*c->lum; fg2=g*c->lum; fb=b*c->lum; }
                    fprintf(out,"<span style='color:#%02x%02x%02x; background-color:#%02x%02x%02x;'>",color_to_int(fr),color_to_int(fg2),color_to_int(fb),R,G,B);
                } else {
                    fprintf(out,"<span style='color:#%02x%02x%02x;'>",R,G,B);
                }
                html_print_char(out,c->ch);
                fputs("</span>",out);
            }
            if(opt_border) fputc('|',out);
            fputs("<br/>",out);
        } else if(!opt_html && color_active){
            for(int64_t x=0;x<outw;x++) print_cell_ansi(out,&cells[y*outw+x],comps);
            if(opt_border) fputc('|',out);
            fputc('\n',out);
        } else {
            // plain: build a NUL-terminated row and print with %s (matching truncation on NUL chars)
            // Allocate per row to avoid a huge persistent buffer for width 0 etc.
            char *rb=malloc((size_t)(outw+1));
            if(rb){
                for(int64_t x=0;x<outw;x++) rb[x]=(char)cells[y*outw+x].ch;
                rb[outw]='\0';
                fprintf(out,"%s",rb);
                free(rb);
            }
            if(opt_border) fputc('|',out);
            fputc('\n',out);
        }
    }
    if(opt_border){
        fputc('+',out); for(int64_t i=0;i<outw;i++) fputc('-',out); fputs("+\n",out);
    }
    if(opt_html && !opt_html_raw){
        fputs("</pre>\n",out);
        fputs("</div>\n",out);
        fputs("</body>\n",out);
        fputs("</html>\n",out);
    }
    fflush(out);
}

// ---- JPEG loading + conversion ----
static void verbose_progress(int64_t row_index_plus2,int srch){
    // bar width 54, hashes = round(54 * (y+2)/srch)
    int64_t hashes = round_div_i64(54*row_index_plus2, srch);
    if(hashes>=57){
        // The reference overflows a fixed buffer here for very short images.
        fprintf(stderr,"*** buffer overflow detected ***: terminated\n");
        fflush(stderr);
        abort();
    }
    fputs("Decompressing image [",stderr);
    for(int64_t i=0;i<hashes;i++) fputc('#',stderr);
    for(int64_t i=hashes;i<54;i++) fputc('.',stderr);
    fputs("]\r",stderr);
    fflush(stderr);
}
static int process_stream(FILE *in){
    void *err=calloc(1,8192);
    void *cinfo=calloc(1,8192);
    if(!err||!cinfo){ free(err);free(cinfo); fprintf(stderr,"Not enough memory for given output dimension\n"); return 1; }
    jpeg_std_error(err);
    *(void**)cinfo=err;
    jpeg_CreateDecompress(cinfo,J_VERSION,J_STRUCT_SIZE);
    jpeg_stdio_src(cinfo,in);
    jpeg_read_header(cinfo,1);
    int srcw=(int)*(unsigned int*)((char*)cinfo+JOFF_IMAGE_WIDTH);
    int srch=(int)*(unsigned int*)((char*)cinfo+JOFF_IMAGE_HEIGHT);
    int num_comp=*(int*)((char*)cinfo+JOFF_NUM_COMPONENTS);
    int64_t outw=0,outh=0;
    compute_output_dims(srcw,srch,&outw,&outh);
    // memory check (matching the reference's apparent INT_MAX product guard)
    __int128 prod=(__int128)outw*outh;
    if(prod>INT_MAX || outw==INT_MAX){
        fprintf(stderr,"Not enough memory for given output dimension\n");
        jpeg_destroy_decompress(cinfo); free(cinfo); free(err);
        return 1;
    }
    Cell *cells=NULL;
    if(outw>0 && outh>0){
        cells=calloc((size_t)(outw*outh),sizeof(Cell));
        if(!cells){ fprintf(stderr,"Not enough memory for given output dimension\n"); jpeg_destroy_decompress(cinfo); free(cinfo); free(err); return 1; }
    } else {
        cells=calloc(1,sizeof(Cell));
    }
    if(opt_verbose){
        fprintf(stderr,"Source width: %d\n",srcw);
        fprintf(stderr,"Source height: %d\n",srch);
        fprintf(stderr,"Source color components: %d\n",num_comp);
        fprintf(stderr,"Output width: %lld\n",(long long)outw);
        fprintf(stderr,"Output height: %lld\n",(long long)outh);
        fprintf(stderr,"Output palette (%d chars): '%s'\n",(int)strlen(palette_buf),palette_buf);
    }
    jpeg_start_decompress(cinfo);
    int out_comps=*(int*)((char*)cinfo+JOFF_OUTPUT_COMPONENTS);
    int libw=(int)*(unsigned int*)((char*)cinfo+JOFF_OUTPUT_WIDTH);
    int libh=(int)*(unsigned int*)((char*)cinfo+JOFF_OUTPUT_HEIGHT);
    if(libw>0){ srcw=libw; }
    if(libh>0){ srch=libh; }
    if(out_comps<=0) out_comps=num_comp>0?num_comp:1;
    size_t row_stride=(size_t)srcw*out_comps;
    unsigned char *pixels=NULL;
    if(srcw>0 && srch>0){
        pixels=malloc(row_stride*(size_t)srch);
        if(!pixels){ fprintf(stderr,"Not enough memory for given output dimension\n"); free(cells); jpeg_destroy_decompress(cinfo); free(cinfo); free(err); return 1; }
    }
    for(int y=0;y<srch;y++){
        unsigned char *row=pixels+row_stride*(size_t)y;
        unsigned char *rows[1]={row};
        jpeg_read_scanlines(cinfo,rows,1);
        if(opt_verbose) verbose_progress(y+2,srch);
    }
    if(opt_verbose) fputc('\n',stderr);
    jpeg_finish_decompress(cinfo);
    jpeg_destroy_decompress(cinfo);
    free(cinfo); free(err);
    // compute bounds
    if(outw>0 && outh>0 && pixels){
        int64_t *xb=malloc(sizeof(int64_t)*(outw+1));
        int64_t *yb=malloc(sizeof(int64_t)*(outh+1));
        if(!xb||!yb){ free(xb);free(yb);free(pixels);free(cells); fprintf(stderr,"Not enough memory for given output dimension\n"); return 1; }
        for(int64_t k=0;k<=outw;k++) xb[k]=round_div_i64(k*(int64_t)(srcw-1),outw);
        if(outh==1){ yb[0]=0; yb[1]=srch-1; }
        else {
            yb[0]=(processed_images>0 && srch>1)?1:0;
            for(int64_t k=1;k<outh;k++) yb[k]=ceil_div_i64((2*k-1)*(int64_t)(srch-1),2*(outh-1));
            yb[outh]=srch-1;
        }
        int pal_len=(int)strlen(palette_buf);
        for(int64_t oy=0;oy<outh;oy++){
            int64_t y0=yb[oy],y1=yb[oy+1];
            if(y1<y0) y1=y0;
            for(int64_t ox=0;ox<outw;ox++){
                int64_t x0=xb[ox],x1=xb[ox+1];
                if(x1<x0) x1=x0;
                float sumL=0,sumR=0,sumG=0,sumB=0;
                for(int64_t yy=y0;yy<=y1;yy++){
                    const unsigned char *prow=pixels+row_stride*(size_t)yy;
                    for(int64_t xx=x0;xx<=x1;xx++){
                        const unsigned char *p=prow+(size_t)xx*out_comps;
                        if(out_comps==3){
                            float rf=p[0]/255.0f, gf=p[1]/255.0f, bf=p[2]/255.0f;
                            sumR+=rf; sumG+=gf; sumB+=bf;
                            sumL += rf*opt_red + gf*opt_green + bf*opt_blue;
                        } else {
                            float vf=p[0]/255.0f;
                            sumR+=vf; sumG+=vf; sumB+=vf; sumL+=vf;
                        }
                    }
                }
                float count=(float)((x1-x0+1)*(y1-y0+1));
                Cell cell;
                cell.lum=sumL/count; cell.r=sumR/count; cell.g=sumG/count; cell.b=sumB/count;
                float lum=cell.lum;
                if(opt_invert) lum=1.0f-lum;
                int idx=(int)(lum*(pal_len-1)+0.5f);
                unsigned char ch=0;
                if(idx>=0 && idx<=256) ch=(unsigned char)palette_buf[idx];
                else ch=0;
                cell.ch=ch;
                int64_t dx=opt_flipx?(outw-1-ox):ox;
                int64_t dy=opt_flipy?(outh-1-oy):oy;
                cells[dy*outw+dx]=cell;
            }
        }
        free(xb);free(yb);
    }
    free(pixels);
    print_image(cells,outw,outh,out_comps);
    free(cells);
    processed_images++;
    return 0;
}
static int is_url(const char *s){
    return starts_with(s,"http://")||starts_with(s,"https://")||starts_with(s,"ftp://")||starts_with(s,"ftps://")||starts_with(s,"file://");
}
static FILE *download_url(const char *url){
    FILE *tmp=tmpfile();
    if(!tmp) return NULL;
    CURL *curl=curl_easy_init();
    if(curl){
        curl_easy_setopt(curl,CURLOPT_URL,url);
        curl_easy_setopt(curl,CURLOPT_WRITEDATA,tmp);
        curl_easy_setopt(curl,CURLOPT_FOLLOWLOCATION,1L);
        curl_easy_setopt(curl,CURLOPT_FAILONERROR,1L);
        if(opt_debug) curl_easy_setopt(curl,CURLOPT_VERBOSE,1L);
        curl_easy_perform(curl);
        curl_easy_cleanup(curl);
    }
    rewind(tmp);
    return tmp;
}
int main(int argc,char **argv){
    strcpy(palette_buf,"   ...',;:clodxkO0KXNWM");
    curl_global_init(CURL_GLOBAL_ALL);
    for(int i=1;i<argc;i++){
        char *arg=argv[i];
        if(strcmp(arg,"-h")==0||strcmp(arg,"--help")==0){ fputs(HELP_TEXT,stderr); return 0; }
        if(strcmp(arg,"-V")==0||strcmp(arg,"--version")==0){ fputs(VERSION_TEXT,stderr); return 0; }
        if(strcmp(arg,"-")==0){ add_file(arg); continue; }
        else if(strcmp(arg,"-b")==0||strcmp(arg,"--border")==0) opt_border=1;
        else if(strcmp(arg,"-d")==0||strcmp(arg,"--debug")==0) opt_debug=1;
        else if(strcmp(arg,"-f")==0||strcmp(arg,"--term-fit")==0) term_mode=TM_FIT;
        else if(strcmp(arg,"--term-width")==0) term_mode=TM_WIDTH;
        else if(strcmp(arg,"--term-height")==0) term_mode=TM_HEIGHT;
        else if(strcmp(arg,"-z")==0||strcmp(arg,"--term-zoom")==0) term_mode=TM_ZOOM;
        else if(strcmp(arg,"-x")==0||strcmp(arg,"--flipx")==0) opt_flipx=1;
        else if(strcmp(arg,"-y")==0||strcmp(arg,"--flipy")==0) opt_flipy=1;
        else if(strcmp(arg,"-i")==0||strcmp(arg,"--invert")==0) opt_invert=!opt_invert;
        else if(strcmp(arg,"--background=dark")==0) opt_invert=0;
        else if(strcmp(arg,"--background=light")==0) opt_invert=1;
        else if(strcmp(arg,"--clear")==0) opt_clear=1;
        else if(strcmp(arg,"--color")==0||strcmp(arg,"--colors")==0) opt_colors=1;
        else if(strcmp(arg,"--fill")==0) opt_fill=1;
        else if(strcmp(arg,"--html-fill")==0){ opt_fill=1; fprintf(stderr,"warning: --html-fill has changed to --fill\n"); }
        else if(strcmp(arg,"--grayscale")==0) opt_grayscale=1;
        else if(strcmp(arg,"--html")==0) opt_html=1;
        else if(strcmp(arg,"--html-no-bold")==0) opt_html_no_bold=1;
        else if(strcmp(arg,"--html-raw")==0) opt_html_raw=1;
        else if(strcmp(arg,"-v")==0||strcmp(arg,"--verbose")==0) opt_verbose=1;
        else if(starts_with(arg,"--chars=")){
            const char *v=arg+8;
            if(strlen(v)>256){ fprintf(stderr,"*** buffer overflow detected ***: terminated\n"); fflush(stderr); abort(); }
            strcpy(palette_buf,v);
        }
        else if(starts_with(arg,"--output=")) output_name=arg+9;
        else if(starts_with(arg,"--html-title=")) html_title=arg+13;
        else if(sscanf(arg,"--width=%d",&opt_width)==1){ width_given=1; if(!height_given) opt_height=0; }
        else if(sscanf(arg,"--height=%d",&opt_height)==1){ height_given=1; if(!width_given) opt_width=0; }
        else if(sscanf(arg,"--size=%dx%d",&opt_width,&opt_height)==2){ width_given=0; height_given=0; }
        else if(sscanf(arg,"--red=%f",&opt_red)==1){}
        else if(sscanf(arg,"--green=%f",&opt_green)==1){}
        else if(sscanf(arg,"--blue=%f",&opt_blue)==1){}
        else if(sscanf(arg,"--html-fontsize=%d",&html_fontsize)==1){}
        else if(arg[0]=='-'){ fprintf(stderr,"Unknown option %s\n\n",arg); fputs(HELP_TEXT,stderr); return 1; }
        else add_file(arg);
    }
    if(num_files==0){ fprintf(stderr,"No files specified.\n\n"); fputs(HELP_TEXT,stderr); return 1; }
    int need_term=0;
    if(term_mode==TM_WIDTH||term_mode==TM_HEIGHT||term_mode==TM_ZOOM) need_term=1;
    else if(opt_width==0 && opt_height==0) need_term=1;
    if(need_term){ if(!get_terminal_size()) return 1; }
    else { term_tw=term_cols-(opt_border?2:0); term_th=term_lines-(opt_border?2:0); }
    if(strlen(palette_buf)<2){ fprintf(stderr,"You must specify at least two characters in --chars.\n"); return 1; }
    if(invalid_global_dims()){ fprintf(stderr,"Invalid width or height specified\n"); return 1; }
    if(opt_red+opt_green+opt_blue != 1.0f){ fprintf(stderr,"Weights RED + GREEN + BLUE must equal 1.0\n"); return 1; }
    out_fp=stdout;
    if(output_name!=NULL){
        if(output_name[0]=='\0'){ fprintf(stderr,"Empty output filename.\n"); return 1; }
        if(strcmp(output_name,"-")!=0){
            out_fp=fopen(output_name,"w");
            if(!out_fp){ fprintf(stderr,"Could not open '%s' for writing.\n",output_name); return 1; }
        }
    }
    int rc=0;
    for(int i=0;i<num_files;i++){
        char *name=files[i];
        if(strcmp(name,"-")==0){
            rc=process_stream(stdin);
            if(rc) break;
        } else if(is_url(name)){
            if(opt_verbose) fprintf(stderr,"URL: %s\n",name);
            FILE *tmp=download_url(name);
            if(!tmp){
                // mimic empty download feeding libjpeg: create an empty tmpfile if possible
                tmp=tmpfile();
                if(!tmp){ rc=1; break; }
            }
            rc=process_stream(tmp);
            fclose(tmp);
            if(rc) break;
        } else {
            FILE *fp=fopen(name,"rb");
            if(!fp){ fprintf(stderr,"Can't open %s\n",name); rc=1; break; }
            if(opt_verbose) fprintf(stderr,"File: %s\n",name);
            rc=process_stream(fp);
            fclose(fp);
            if(rc) break;
        }
    }
    if(out_fp && out_fp!=stdout) fclose(out_fp);
    else if(out_fp) fflush(out_fp);
    curl_global_cleanup();
    return rc;
}
