s=open('jp2a.c').read()
old='''    // achromatic / near-achromatic: exact greys (and very bright near-whites) are white; other desaturated colours are black
    if(mx-mn <= 0.1f){ if(mx==mn || mn >= 0.78f) return 7; return 0; }'''
new='''    // Low-saturation colours: exact greys are white.  Otherwise the
    // reference treats desaturated colours as black when green is a
    // maximal component, and as white (when not too dark) otherwise.
    {
        float sat = mx>0 ? (mx-mn)/mx : 0.0f;
        if(sat <= 0.12f){
            if(mx==mn) return 7;
            if(g>=r && g>=b) return 0;
            return mx > 0.5f ? 7 : 0;
        }
    }'''
assert old in s
open('jp2a.c','w').write(s.replace(old,new))
