import subprocess,os
def r(a,env=None):
 e={**os.environ,"TERM":"xterm"}
 if env:
  for k,v in env.items(): 
   if v is None:e.pop(k,None)
   else:e[k]=v
 p=subprocess.run(["./executable"]+a,capture_output=True,env=e);print(a,p.returncode,p.stderr[:90])
img="assets/logo-40x25-gray.jpg"
r(["--chars=x","--red=0.3","--size=2x2",img])
r(["--red=0.3","--size=0x5",img])
r(["--chars=x","--size=0x5",img])
r(["--output=/nope/x","--size=0x5",img])
r(["--output=","--red=0.3","--size=2x2",img])
r(["--chars=x",img],{"TERM":None})
r(["--red=0.3",img],{"TERM":None})
r(["--red=0.3","--size=2x2",img],{"TERM":None})
